from typing import List

def minArraySum(nums: List[int], k: int, op1: int, op2: int) -> int:
    n = len(nums)
    # dp[j][l] is the minimum sum using j Op1 and l Op2
    # Initialize with a very large value
    inf = float('inf')
    dp = [[inf] * (op2 + 1) for _ in range(op1 + 1)]
    dp[0][0] = 0

    for x in nums:
        next_dp = [[inf] * (op2 + 1) for _ in range(op1 + 1)]
        for j in range(op1 + 1):
            for l in range(op2 + 1):
                if dp[j][l] == inf:
                    continue

                current_sum = dp[j][l]

                # Option 0: No operation
                if current_sum + x < next_dp[j][l]:
                    next_dp[j][l] = current_sum + x

                # Option 1: Op1 only
                if j + 1 <= op1:
                    v1 = (x + 1) // 2
                    if current_sum + v1 < next_dp[j+1][l]:
                        next_dp[j+1][l] = current_sum + v1

                # Option 2: Op2 only
                if l + 1 <= op2 and x >= k:
                    v2 = x - k
                    if current_sum + v2 < next_dp[j][l+1]:
                        next_dp[j][l+1] = current_sum + v2

                # Option 3: Both operations
                if j + 1 <= op1 and l + 1 <= op2:
                    # Op1 then Op2
                    v1 = (x + 1) // 2
                    res_a = v1 - k if v1 >= k else v1

                    # Op2 then Op1
                    res_b = inf
                    if x >= k:
                        v2 = x - k
                        res_b = (v2 + 1) // 2

                    best_both = min(res_a, res_b)
                    if current_sum + best_both < next_dp[j+1][l+1]:
                        next_dp[j+1][l+1] = current_sum + best_both
        dp = next_dp

    ans = inf
    for j in range(op1 + 1):
        for l in range(op2 + 1):
            if dp[j][l] < ans:
                ans = dp[j][l]
    return int(ans)

from typing import List

def maxRectangleArea(points: List[List[int]]) -> int:
    max_area = -1
    n = len(points)

    # Iterate through all combinations of 4 points
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    p_indices = [i, j, k, l]
                    pts = [points[idx] for idx in p_indices]

                    # Check if these 4 points form an axis-aligned rectangle
                    xs = sorted(list(set(p[0] for p in pts)))
                    ys = sorted(list(set(p[1] for p in pts)))

                    if len(xs) == 2 and len(ys) == 2:
                        # Check if the 4 points are exactly (x1, y1), (x1, y2), (x2, y1), (x2, y2)
                        expected_pts = {
                            (xs[0], ys[0]),
                            (xs[0], ys[1]),
                            (xs[1], ys[0]),
                            (xs[1], ys[1])
                        }
                        actual_pts = set()
                        for p in pts:
                            actual_pts.add((p[0], p[1]))

                        if actual_pts == expected_pts:
                            # It's a rectangle. Now check if any other point is inside or on the border.
                            x_min, x_max = xs[0], xs[1]
                            y_min, y_max = ys[0], ys[1]

                            is_valid = True
                            for m in range(n):
                                if m not in p_indices:
                                    pm = points[m]
                                    if x_min <= pm[0] <= x_max and y_min <= pm[1] <= y_max:
                                        is_valid = False
                                        break

                            if is_valid:
                                area = (x_max - x_min) * (y_max - y_min)
                                if area > max_area:
                                    max_area = area

    return max_area

from typing import List

def resultsArray(nums: List[int], k: int) -> List[int]:
    n = len(nums)
    results = []
    for i in range(n - k + 1):
        subarray = nums[i : i + k]
        is_consecutive_sorted = True
        for j in range(k - 1):
            if subarray[j+1] != subarray[j] + 1:
                is_consecutive_sorted = False
                break

        if is_consecutive_sorted:
            results.append(subarray[-1])
        else:
            results.append(-1)
    return results

